#!/usr/bin/env bash
# Offline check of rt_cask_local_origin against a real GoReleaser cask
# (fixtures/goreleaser-cask.rb, generated by goreleaser 2.18.3). No Docker.
set -euo pipefail
here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source-path=SCRIPTDIR source=../lib.sh
. "$here/../lib.sh"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
cp "$here/goreleaser-cask.rb" "$tmp/homebot.rb"
want=$(grep -c 'https://github.com/hyperlab-sh/homebot/releases/download/' "$tmp/homebot.rb")
(( want == 4 )) || { echo "cask-rewrite-check: fixture has $want release URLs, want 4" >&2; exit 1; }
rt_cask_local_origin "$tmp/homebot.rb" 8765
got=$(grep -cF 'url "http://127.0.0.1:8765/v#{version}/homebot_#{version}_' "$tmp/homebot.rb")
(( got == 4 )) || { echo "cask-rewrite-check: $got rewritten URLs, want 4" >&2; exit 1; }
# A cask with no release URL must make the helper die, not pass.
printf 'cask "x" do\nend\n' >"$tmp/empty.rb"
if (rt_cask_local_origin "$tmp/empty.rb" 8765) 2>/dev/null; then
  echo 'cask-rewrite-check: helper accepted a cask with no release URL' >&2; exit 1
fi
echo 'cask-rewrite-check: ok (4 URLs rewritten)'
